      out.write("<script>\r\n");
      out.write("// Danh sách lý do riêng cho từng trạng thái kết thúc\r\n");
      out.write("const REASON_PRESETS = {\r\n");
      out.write("    'FULFILLED': [\r\n");
      out.write("        'Đã tuyển đủ số lượng chỉ tiêu (Headcount)',\r\n");
      out.write("        'Đã ký hợp đồng thử việc và tiếp nhận đủ ứng viên',\r\n");
      out.write("        'Tuyển vượt chỉ tiêu xuất sắc',\r\n");
      out.write("        'Ứng viên nội bộ đã được điều chuyển đáp ứng đủ yêu cầu',\r\n");
      out.write("        'Khác...'\r\n");
      out.write("    ],\r\n");
      out.write("    'PAUSED': [\r\n");
      out.write("        'Tạm dừng kế hoạch tuyển dụng quý này',\r\n");
      out.write("        'Đóng băng ngân sách tuyển dụng (Budget freeze)',\r\n");
      out.write("        'Chờ tái cơ cấu tổ chức / phòng ban chuyên môn',\r\n");
      out.write("        'Thay đổi yêu cầu năng lực vị trí cần chuẩn bị lại JD',\r\n");
      out.write("        'Khác...'\r\n");
      out.write("    ],\r\n");
      out.write("    'CANCELLED': [\r\n");
      out.write("        'Huỷ bỏ vị trí do thay đổi chiến lược kinh doanh',\r\n");
      out.write("        'Dự án bị huỷ bỏ hoặc thu hẹp quy mô hoạt động',\r\n");
      out.write("        'Chuyển giao vị trí sang đơn vị thành viên khác phụ trách',\r\n");
      out.write("        'Không còn nhu cầu tuyển dụng vị trí này',\r\n");
      out.write("        'Khác...'\r\n");
      out.write("    ]\r\n");
      out.write("};\r\n");
      out.write("\r\n");
      out.write("function onStatusChanged() {\r\n");
      out.write("    const selectedStatus = document.querySelector('input[name=\"terminalStatus\"]:checked').value;\r\n");
      out.write("    const reasonSelect = document.getElementById('closeReasonSelect');\r\n");
      out.write("    reasonSelect.innerHTML = '';\r\n");
      out.write("\r\n");
      out.write("    const list = REASON_PRESETS[selectedStatus] || ['Lý do khác...'];\r\n");
      out.write("    list.forEach(r => {\r\n");
      out.write("        const opt = document.createElement('option');\r\n");
      out.write("        opt.value = r;\r\n");
      out.write("        opt.textContent = r;\r\n");
      out.write("        reasonSelect.appendChild(opt);\r\n");
      out.write("    });\r\n");
      out.write("\r\n");
      out.write("    onReasonSelectChanged();\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("function onReasonSelectChanged() {\r\n");
      out.write("    const select = document.getElementById('closeReasonSelect');\r\n");
      out.write("    const customWrapper = document.getElementById('customReasonWrapper');\r\n");
      out.write("    const customInput = document.getElementById('customReasonInput');\r\n");
      out.write("    const finalReason = document.getElementById('finalCloseReason');\r\n");
      out.write("\r\n");
      out.write("    if (select.value === 'Khác...') {\r\n");
      out.write("        customWrapper.style.display = 'block';\r\n");
      out.write("        finalReason.value = customInput.value.trim() || 'Lý do khác';\r\n");
      out.write("    } else {\r\n");
      out.write("        customWrapper.style.display = 'none';\r\n");
      out.write("        finalReason.value = select.value;\r\n");
      out.write("    }\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("document.getElementById('customReasonInput').addEventListener('input', function() {\r\n");
      out.write("    if (document.getElementById('closeReasonSelect').value === 'Khác...') {\r\n");
      out.write("        document.getElementById('finalCloseReason').value = this.value.trim();\r\n");
      out.write("    }\r\n");
      out.write("});\r\n");
      out.write("\r\n");
      out.write("function openCloseModal(id, code, positionTitle) {\r\n");
      out.write("    document.getElementById('closeReqId').value = id;\r\n");
      out.write("    document.getElementById('closeModalSubtitle').textContent = code + ' - ' + positionTitle;\r\n");
      out.write("    \r\n");
      out.write("    // Reset form & radios\r\n");
      out.write("    document.querySelector('input[name=\"terminalStatus\"][value=\"FULFILLED\"]').checked = true;\r\n");
      out.write("    onStatusChanged();\r\n");
      out.write("    document.getElementById('closeNotes').value = '';\r\n");
      out.write("\r\n");
      out.write("    // Reset UI pipeline\r\n");
      out.write("    document.getElementById('pipelineLoading').style.display = 'block';\r\n");
      out.write("    document.getElementById('pipelineWarningBox').style.display = 'none';\r\n");
      out.write("    document.getElementById('pipelineSafeBox').style.display = 'none';\r\n");
      out.write("    document.getElementById('postingsStatusText').innerHTML = '<span class=\"spinner-border spinner-border-sm text-info me-1\" role=\"status\"></span> Đang kiểm tra tin tuyển dụng...';\r\n");
      out.write("\r\n");
      out.write("    const modal = new bootstrap.Modal(document.getElementById('closeModal'));\r\n");
      out.write("    modal.show();\r\n");
      out.write("\r\n");
      out.write("    // Gọi API check pipeline ứng viên và tin đăng\r\n");
      out.write("    fetch('");
      out.write((java.lang.String) org.apache.jasper.runtime.PageContextImpl.proprietaryEvaluate("${pageContext.request.contextPath}", java.lang.String.class, (javax.servlet.jsp.PageContext)_jspx_page_context, null, false));
      out.write("/recruitment-requests/check-pipeline?id=' + encodeURIComponent(id))\r\n");
      out.write("        .then(res => res.json())\r\n");
      out.write("        .then(data => {\r\n");
      out.write("            document.getElementById('pipelineLoading').style.display = 'none';\r\n");
      out.write("\r\n");
      out.write("            // Cập nhật trạng thái tin tuyển dụng\r\n");
      out.write("            const postingsCount = data.activePostingsCount || 0;\r\n");
      out.write("            if (postingsCount > 0) {\r\n");
      out.write("                document.getElementById('postingsStatusText').innerHTML = \r\n");
      out.write("                    '<i class=\"bi bi-check-circle text-primary me-1\"></i> Phát hiện <strong>' + postingsCount + ' tin tuyển dụng đang đăng</strong> sẽ được tự động gỡ khi xác nhận.';\r\n");
      out.write("            } else {\r\n");
      out.write("                document.getElementById('postingsStatusText').innerHTML = \r\n");
      out.write("                    '<i class=\"bi bi-info-circle text-muted me-1\"></i> Không có tin tuyển dụng nào đang đăng công khai.';\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            // Cập nhật trạng thái ứng viên trong pipeline\r\n");
      out.write("            const candidates = data.activeCandidates || [];\r\n");
      out.write("            const count = candidates.length;\r\n");
      out.write("\r\n");
      out.write("            if (count > 0) {\r\n");
      out.write("                document.getElementById('pipelineWarningBox').style.display = 'block';\r\n");
      out.write("                document.getElementById('pipelineSafeBox').style.display = 'none';\r\n");
      out.write("                document.getElementById('candidateCountNumber').textContent = count;\r\n");
      out.write("\r\n");
      out.write("                const tbody = document.getElementById('pipelineCandidateListBody');\r\n");
      out.write("                tbody.innerHTML = '';\r\n");
      out.write("                candidates.forEach(c => {\r\n");
      out.write("                    let badgeClass = 'bg-secondary';\r\n");
      out.write("                    let badgeLabel = c.status;\r\n");
      out.write("                    if (c.status === 'APPLIED') { badgeClass = 'bg-primary'; badgeLabel = 'Mới ứng tuyển'; }\r\n");
      out.write("                    else if (c.status === 'SCREENING') { badgeClass = 'bg-info text-dark'; badgeLabel = 'Sàng lọc'; }\r\n");
      out.write("                    else if (c.status === 'INTERVIEWING') { badgeClass = 'bg-warning text-dark'; badgeLabel = 'Phỏng vấn'; }\r\n");
      out.write("                    else if (c.status === 'OFFER') { badgeClass = 'bg-purple text-white'; badgeLabel = 'Đã gửi Offer'; }\r\n");
      out.write("\r\n");
      out.write("                    const tr = document.createElement('tr');\r\n");
      out.write("                    tr.innerHTML = `\r\n");
      out.write("                        <td class=\"fw-semibold\">${escapeHtml(c.fullName)}</td>\r\n");
      out.write("                        <td class=\"text-muted\">${escapeHtml(c.email)}</td>\r\n");
      out.write("                        <td><span class=\"badge ${badgeClass} font-monospace\">${badgeLabel}</span></td>\r\n");
      out.write("                    `;\r\n");
      out.write("                    tbody.appendChild(tr);\r\n");
      out.write("                });\r\n");
      out.write("\r\n");
      out.write("                // Kích hoạt radio action\r\n");
      out.write("                document.getElementById('actionReject').disabled = false;\r\n");
      out.write("                document.getElementById('actionHold').disabled = false;\r\n");
      out.write("                document.getElementById('actionManual').disabled = false;\r\n");
      out.write("                document.getElementById('actionReject').checked = true;\r\n");
      out.write("            } else {\r\n");
      out.write("                document.getElementById('pipelineWarningBox').style.display = 'none';\r\n");
      out.write("                document.getElementById('pipelineSafeBox').style.display = 'block';\r\n");
      out.write("\r\n");
      out.write("                document.getElementById('actionReject').disabled = true;\r\n");
      out.write("                document.getElementById('actionHold').disabled = true;\r\n");
      out.write("                document.getElementById('actionManual').disabled = true;\r\n");
      out.write("                document.getElementById('safeCandidateAction').disabled = false;\r\n");
      out.write("            }\r\n");
      out.write("        })\r\n");
      out.write("        .catch(err => {\r\n");
      out.write("            document.getElementById('pipelineLoading').innerHTML = \r\n");
      out.write("                '<span class=\"text-danger\"><i class=\"bi bi-exclamation-circle me-1\"></i> Không thể tải dữ liệu pipeline: ' + escapeHtml(err.message) + '</span>';\r\n");
      out.write("        });\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("var currentDetailId = null;\r\n");
      out.write("var currentApprovalReqId = null;\r\n");
